const TOTAL=175;let running=false,paused=false,score=0,lives=3,travel=0,playerSpeed=9.6,vy=0,grounded=true,slideTime=0,checkpoint=-1,shake=0,elapsed=0;
let lane=0,targetX=0;const keys={};
const overlay=document.querySelector('#overlay'),titleEl=document.querySelector('#title'),eyebrow=document.querySelector('#eyebrow'),messageEl=document.querySelector('#message'),playBtn=document.querySelector('#play');
