let audio=null,muted=false;
function beep(freq=520,duration=.08,type='sine',volume=.035){if(muted)return;try{audio??=new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch{}}
function announce(text){toast.textContent=text;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1250)}
function showOverlay(mode){overlay.classList.remove('hidden');if(mode==='start'){eyebrow.textContent='A WILD RUN BEGINS';titleEl.innerHTML='RELIC<br>RUN';messageEl.textContent='Dash through the sunken jungle, snatch the wumpa fruit, and make it to the temple. Mind the gaps!';playBtn.textContent='START RUN'}else if(mode==='dead'){eyebrow.textContent='THE JUNGLE WINS THIS ROUND';titleEl.innerHTML='RUN<br>OVER';messageEl.textContent=`You collected ${score} fruit. Catch your breath and take another shot at the temple.`;playBtn.textContent='TRY AGAIN'}else{eyebrow.textContent='TEMPLE RAID COMPLETE';titleEl.innerHTML='RELIC<br>FOUND!';messageEl.textContent=`Beautiful run! You made it to the temple with ${score} fruit.`;playBtn.textContent='RUN AGAIN'}}
function resetGame(){score=0;lives=3;travel=0;lane=0;targetX=0;vy=0;grounded=true;slideTime=0;checkpoint=-1;player.position.set(0,0,1);avatar.rotation.set(0,0,0);fruitMeshes.forEach(f=>{f.got=false;f.mesh.visible=true});hazardMeshes.forEach(h=>h.mesh.visible=true);fruitEl.textContent='0';livesEl.textContent='3';progressEl.style.width='0%';distanceEl.textContent='0%';running=true;paused=false;overlay.classList.add('hidden');beep(640,.12,'triangle')}
function startJump(){if(!running||paused||!grounded)return;vy=8.9;grounded=false;beep(390,.09,'triangle')}
function changeLane(dir){if(!running||paused)return;lane=Math.max(-1,Math.min(1,lane+dir));targetX=lane*2.35;}
function slide(){if(running&&!paused&&grounded){slideTime=.62;beep(220,.05,'square',.018)}}
function inputDown(e){if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' ','a','d','w','s'].includes(e.key))e.preventDefault();if(keys[e.key])return;keys[e.key]=true;if(e.key==='ArrowLeft'||e.key==='a')changeLane(-1);if(e.key==='ArrowRight'||e.key==='d')changeLane(1);if(e.key===' '||e.key==='ArrowUp'||e.key==='w')startJump();if(e.key==='ArrowDown'||e.key==='s')slide();if(e.key==='Escape'&&running){paused=!paused;if(paused)announce('PAUSED · PRESS ESC TO RESUME')}}
function inputUp(e){keys[e.key]=false}
addEventListener('keydown',inputDown);addEventListener('keyup',inputUp);addEventListener('blur',()=>{keys[' ']=false});
document.querySelector('#left').addEventListener('pointerdown',e=>{e.preventDefault();changeLane(-1)});document.querySelector('#right').addEventListener('pointerdown',e=>{e.preventDefault();changeLane(1)});document.querySelector('#jump').addEventListener('pointerdown',e=>{e.preventDefault();startJump()});
document.querySelector('#sound').addEventListener('click',()=>{muted=!muted;document.querySelector('#sound').textContent=muted?'♫̸':'♫'});
playBtn.addEventListener('click',resetGame);
function isGap(z){return gaps.some(([a,b])=>z<a+.2&&z>b-.2)}
function hurt(){lives--;livesEl.textContent=String(lives);shake=.48;beep(105,.35,'sawtooth',.045);if(lives<=0){running=false;showOverlay('dead');return}player.position.z=checkpoint<0?1:checkpoint;travel=checkpoint<0?0:Math.abs(checkpoint-1);lane=0;targetX=0;player.position.x=0;player.position.y=0;vy=0;grounded=true;announce(checkpoint<0?'MASK LOST · TRY AGAIN':'CHECKPOINT · KEEP GOING')}
function update(dt){elapsed+=dt;if(!running||paused)return;const safeDt=Math.min(dt,.04);travel+=playerSpeed*safeDt;player.position.z=1-travel;player.position.x+= (targetX-player.position.x)*Math.min(1,safeDt*13);
 // Jump arc and fall detection over the breaks.
 if(!grounded){vy-=21*safeDt;player.position.y+=vy*safeDt;if(player.position.y<=0){player.position.y=0;vy=0;grounded=true}}
 slideTime=Math.max(0,slideTime-safeDt);const crouch=slideTime>0?0.57:1;avatar.scale.y+=(crouch-avatar.scale.y)*Math.min(1,safeDt*18);
 if(isGap(player.position.z)&&player.position.y<.03){hurt();if(!running)return}else if(player.position.z<courseEnd-1){running=false;showOverlay('win');beep(780,.3,'triangle')}
 // Obstacles are generous to read but still demand a clear jump, slide, or lane change.
 for(const h of hazardMeshes){if(!h.mesh.visible)continue;if(Math.abs(player.position.z-h.z)<.72&&Math.abs(player.position.x-h.x)<.92){const passed=h.type==='jump'?player.position.y>.48:h.type==='slide'?slideTime>0:false;if(!passed){if(h.type==='jump')h.mesh.visible=false;hurt();if(!running)return;break}}}
 for(const f of fruitMeshes){if(f.got)continue;f.mesh.rotation.y+=safeDt*1.6;f.mesh.position.y=f.y+Math.sin(elapsed*3+f.phase)*.1;if(Math.abs(player.position.z-f.z)<.85&&Math.abs(player.position.x-f.x)<.82&&Math.abs(player.position.y+1-f.y)<1.05){f.got=true;f.mesh.visible=false;score++;fruitEl.textContent=String(score);beep(760+Math.min(score,12)*22,.085,'sine',.025)}}
 for(const cp of [-83,-128]){if(checkpoint>cp&&travel>=Math.abs(cp-1)){checkpoint=cp;announce('CHECKPOINT REACHED');beep(610,.18,'triangle')}}
 const progress=Math.min(100,travel/TOTAL*100);progressEl.style.width=`${progress}%`;distanceEl.textContent=`${Math.floor(progress)}%`;
 // Run cycle, squash on landing, and camera follow with a tiny cinematic impact shake.
 const stride=Math.sin(elapsed*15)*(grounded?1:.2);legs.forEach((leg,i)=>{leg.rotation.x=stride*(i===0?1:-1)*.7});avatar.rotation.z+=(Math.sin(elapsed*7)*.035-avatar.rotation.z)*safeDt*4;avatar.position.y=grounded?Math.abs(Math.sin(elapsed*15))*.055:0;
 camera.position.x+=(player.position.x*.32-camera.position.x)*safeDt*2.2;camera.position.y+=(5.8+player.position.y*.2-camera.position.y)*safeDt*2.5;camera.position.z+=(player.position.z+9.4-camera.position.z)*safeDt*3.2;
 const target=new THREE.Vector3(player.position.x*.22,1.05+player.position.y*.16,player.position.z-5);if(shake>0){shake=Math.max(0,shake-safeDt);target.x+=(Math.random()-.5)*shake*1.5;target.y+=(Math.random()-.5)*shake}camera.lookAt(target);
}
const clock=new THREE.Clock();function frame(){requestAnimationFrame(frame);const dt=clock.getDelta();update(dt);renderer.render(scene,camera)}frame();
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}addEventListener('resize',resize);
showOverlay('start');
</script>
